target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite
make >/dev/null 2>&1   # rebuild non-debug for speed
./collatz_tests tilt-law --octave-min 24 --seeds-per-octave 60000 --apertures 6 --crit-mode height --output-dir out >/dev/null 2>&1
echo "annealed p_b: 0.5000 0.2500 0.1250 0.0625   |   critical p^(1): 0.7500 0.1875 0.0469 0.0117"
echo "=== MIDDLE segments (boundary-excluded bulk), by length band, octave 24, rise>=6 ==="
awk -F, '!/^#/ && $5=="middle" {
    L=$7; band=(L<32)?"016-031":(L<64)?"032-063":(L<128)?"064-127":(L<256)?"128-255":"256+";
    n[band]++; P1[band]+=$8;P2[band]+=$9;P3[band]+=$10;P4[band]+=$11; E[band]+=$17; K1[band]+=$14; K0[band]+=$13 }
  END{ printf "%-9s %6s  %6s %6s %6s %6s  %7s %8s %8s\n","band","n","p1","p2","p3","p4","H/dig","KL_p1","KL_ann";
       split("016-031 032-063 064-127 128-255 256+",o," ");
       for(i=1;i<=5;i++){b=o[i]; if(n[b])printf "%-9s %6d  %.4f %.4f %.4f %.4f  %.4f  %.4f  %.4f\n",b,n[b],P1[b]/n[b],P2[b]/n[b],P3[b]/n[b],P4[b]/n[b],E[b]/n[b],K1[b]/n[b],K0[b]/n[b]} }' out/tilt_law.csv
